(* [comment removed for export] *)
Lemma rl2_T : forall regs m (srow drow n4 k : Z),
  (0 <= k < 32)%Z ->
  getr regs 30 = Z_to_bv 64 srow -> getr regs 31 = Z_to_bv 64 drow -> getr regs 9 = Z_to_bv 64 n4 -> getr regs 15 = Z_to_bv 64 k ->
  exists regs',
    msteps SEGS (mkst regs (0x7aaf4 : word) m rom) (mkst regs' (if Z.eq_dec k 0 then (0x7aab4 : word) else (0x7aa9c : word)) m rom)
    /\ getr regs' 8 = Z_to_bv 64 (drow + n4) /\ getr regs' 9 = Z_to_bv 64 (srow + n4)
    /\ regs_agree (fun r => In r [8; 9]%list) regs regs'.
