  rdn SEGS m (Z_to_bv 64 ps) 4 = Some bsr -> bytes_le_to_Z bsr = bv_unsigned vs ->
  store_ok SEGS m (Z_to_bv 64 pd) 4 = true ->
  getr regs 8 = Z_to_bv 64 pd -> getr regs 9 = Z_to_bv 64 ps ->
  exists regs' (w : word),
    msteps SEGS (mkst regs (0x7aa9c : word) m rom) (mkst regs' (0x7aab4 : word) (wbytes m (Z_to_bv 64 pd) (word_to_le_bytes 4 w)) rom)
    /\ regs_agree (fun r => In r [9; 18]%list) regs regs'.
Proof.
